const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const startDate = '2020-04-20';
  const endDate = '2020-05-12';

  // Define geometries for Shanghai and Wuhan (using approximate city centers)
  const shanghai = ee.Geometry.Point([121.4737, 31.2304]); // Shanghai
  const wuhan = ee.Geometry.Point([114.3055, 30.5928]);    // Wuhan

  // Define a buffer around each point to represent the city area for mean calculation
  const bufferSize = 10000; // 10 km buffer
  const shanghaiGeom = shanghai.buffer(bufferSize);
  const wuhanGeom = wuhan.buffer(bufferSize);

  const bandName = 'tropospheric_NO2_column_number_density';
  const qaBand = 'qa_value';

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(startDate, endDate)
    .filterBounds(shanghaiGeom.union(wuhanGeom));

  const initialCollectionSize = await collection.size().getInfo();
  console.log(`Initial S5P NO2 collection size: ${initialCollectionSize}`);

  if (initialCollectionSize === 0) {
    console.log("C1: Empty Collection (No images found for the specified date/location).");
    return;
  }

  // 3. Processing
  // Filter for good quality data (qa_value > 0.75)
  collection = collection.map(image => image.updateMask(image.select(qaBand).gt(0.75)));

  // Compute the mean image for the period
  const meanImage = collection.select(bandName).mean();

  if (!meanImage) {
    console.log("C3: Calculation Failure (Could not compute mean image).");
    return;
  }

  const scale = 1000; // S5P resolution is ~5.5km x 3.5km, so 1000m is fine.

  // Calculate mean NO2 for Shanghai
  const shanghaiStats = await meanImage.reduceRegion({
    reducer: ee.Reducer.mean().setOutputs(['mean_no2']).count().setOutputs(['pixel_count']),
    geometry: shanghaiGeom,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const shanghaiMean = shanghaiStats ? shanghaiStats['mean_no2'] : null;
  const shanghaiPixels = shanghaiStats ? shanghaiStats['pixel_count'] : 0;

  // Calculate mean NO2 for Wuhan
  const wuhanStats = await meanImage.reduceRegion({
    reducer: ee.Reducer.mean().setOutputs(['mean_no2']).count().setOutputs(['pixel_count']),
    geometry: wuhanGeom,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const wuhanMean = wuhanStats ? wuhanStats['mean_no2'] : null;
  const wuhanPixels = wuhanStats ? wuhanStats['pixel_count'] : 0;

  console.log(`Shanghai: Mean NO2: ${shanghaiMean !== null ? shanghaiMean.toExponential(2) : 'N/A'} mol/m^2, Valid Pixels: ${shanghaiPixels}`);
  console.log(`Wuhan: Mean NO2: ${wuhanMean !== null ? wuhanMean.toExponential(2) : 'N/A'} mol/m^2, Valid Pixels: ${wuhanPixels}`);

  if (shanghaiPixels === 0 || wuhanPixels === 0) {
    console.log("C2: No Valid Pixels (After cloud/quality masking, 0 pixels remain for one or both cities).");
    return;
  }

  // 4. Validation & Final Answer
  if (shanghaiMean === null || isNaN(shanghaiMean) || wuhanMean === null || isNaN(wuhanMean)) {
    console.log("C3: Calculation Failure (Mean NO2 value is invalid for one or both cities).");
  } else if (shanghaiMean > wuhanMean) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
